'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createLimitCache, createFocusState } = require('../node/scheduler-hotpath.cjs');
const { createRenderMemoryFairness } = require('../node/render-memory-fairness.cjs');

// Exact inline getState generated by render-memory-install.py v2 (reference).
function referenceState({ pX, XBe, KBe, jp }) {
  return request => {
    const s = pX('render'), ready = s.waiters.filter(w => ['frameshift', 'remotion'].includes(w.resourceKey)
      && XBe('render', w.jobId, KBe('render'), w.resourceKey, w.priority) === null);
    let focus = null;
    for (const [jobId, job] of jp) {
      if (typeof job.priority !== 'string') throw Error('Invalid native focus priority');
      if (!focus || job.priority < focus.priority) focus = { jobId, priority: job.priority };
    }
    return { render: s, waitingSinceMs: Date.parse(s.memoryWait?.waitingSinceIso), hasReadyRender: ready.length > 0,
      focus: focus && { ...focus, hasReadyRender: ready.some(w => w.jobId === focus.jobId && w.priority === focus.priority) },
      requestPriority: jp.get(request?.jobId)?.priority };
  };
}

function rng(seed) { return () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648; }

function world(r, active) {
  const jobs = Array.from({ length: 1 + Math.floor(r() * 6) }, (_, i) => 'job' + i);
  const jp = new Map(jobs.filter(() => r() < 0.8).map(id => [id, { priority: String(Math.floor(r() * 4)) }]));
  const kinds = ['frameshift', 'remotion', 'ffmpeg', 'geomap'];
  const waiters = Array.from({ length: Math.floor(r() * 40) }, () => {
    const jobId = jobs[Math.floor(r() * jobs.length)];
    return { jobId, resourceKey: kinds[Math.floor(r() * kinds.length)], priority: jp.get(jobId)?.priority ?? '9' };
  });
  const blocked = new Set(jobs.filter(() => r() < 0.5).map(j => j + (r() < 0.5 ? '|frameshift' : '|remotion')));
  const s = { activeTotal: active, waiters, memoryWait: { reasonKey: 'live_headroom', waitingSinceIso: new Date(1000).toISOString() } };
  let calls = 0;
  const XBe = (lane, jobId, limit, resource) => { calls++; assert.equal(limit, 5); return blocked.has(jobId + '|' + resource) ? 'resource' : null; };
  return { native: { pX: () => s, XBe, KBe: () => 5, jp }, calls: () => calls };
}

test('idle render lane: identical result to inline reference, fewer admission checks', () => {
  const r = rng(7);
  for (let i = 0; i < 2000; i++) {
    const a = world(rng(i + 1), 0), b = world(rng(i + 1), 0);
    const request = { jobId: 'job' + Math.floor(r() * 6) };
    assert.deepEqual(createFocusState(a.native)(request), referenceState(b.native)(request));
    assert.ok(a.calls() <= b.calls());
  }
});

test('active render lane: fairness gate decisions and stats identical to reference', () => {
  for (let i = 0; i < 300; i++) {
    const a = world(rng(i + 11), 1 + (i % 4)), b = world(rng(i + 11), 1 + (i % 4));
    let t = 100000;
    const gate = () => true, now = () => t;
    const fast = createRenderMemoryFairness(gate, { getState: createFocusState(a.native), now });
    const ref = createRenderMemoryFairness(gate, { getState: referenceState(b.native), now });
    for (const job of ['job0', 'job1', 'job2']) {
      t += 7000;
      const req = { lane: 'ffmpeg', key: 'ffmpeg', jobId: job };
      assert.deepEqual(fast(req), ref(req));
      assert.deepEqual(fast.getStats(), ref.getStats());
    }
    assert.equal(a.calls(), 0);
  }
});

test('invalid native priority still raises like the reference', () => {
  const { native } = world(rng(3), 0);
  native.jp.set('bad', { priority: 1 });
  assert.throws(() => createFocusState(native)(), /Invalid native priority/);
});

test('limit cache: one read per ttl, writers invalidate even on error', () => {
  let reads = 0, value = 2, t = 0;
  const cache = createLimitCache(() => { reads++; return value; }, { now: () => t });
  for (let i = 0; i < 1000; i++) assert.equal(cache.limit(), 2);
  assert.equal(reads, 1);
  value = 3;
  const write = cache.wrapWriter(v => { value = v; });
  write(4);
  assert.equal(cache.limit(), 4);
  const failing = cache.wrapWriter(() => { value = 6; throw Error('boom'); });
  assert.throws(() => failing(), /boom/);
  assert.equal(cache.limit(), 6);
  value = 7; t = 999; assert.equal(cache.limit(), 6);
  t = 1000; assert.equal(cache.limit(), 7);
  t = 10; assert.equal(cache.limit(), 7, 'clock going backwards forces a fresh read');
  assert.equal(cache.stats.misses, 5);
});
